<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/attendance-schema.php';ensureAttendanceTimeOutColumn($conn);require '../includes/teacher-profile-schema.php';ensureTeacherProfileColumns($conn);require '../includes/xlsx-export.php';
$section=trim($_GET['section']??'all');$date=$_GET['date']??date('Y-m-d');$student=trim($_GET['student']??'');$allDates=($_GET['all_dates']??'')==='1';if(!$allDates&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){http_response_code(400);exit('Invalid date.');}if($allDates&&$student===''){http_response_code(400);exit('A student is required when exporting all dates.');}
$teacherId=(int)($_SESSION['teacher-id']??0);$teacherQuery=$conn->prepare('SELECT GRADE FROM teachers WHERE TEACHER_ID=? LIMIT 1');$teacherQuery->bind_param('i',$teacherId);$teacherQuery->execute();$teacherGrade=(int)(($teacherQuery->get_result()->fetch_assoc()?:[])['GRADE']??0);if(!in_array($teacherGrade,[7,8,9,10,11,12],true)){http_response_code(403);exit('Your teacher account does not have an assigned grade.');}
if($allDates){$stmt=$conn->prepare("SELECT a.STUDENT_ID,COALESCE(s.STUDENT_NAME,a.STUDENT_NAME) STUDENT_NAME,s.SECTION,a.TIME_IN,a.TIME_OUT FROM attendance a INNER JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) WHERE a.STUDENT_ID=? AND s.GRADE=? ORDER BY a.TIME_IN DESC");$stmt->bind_param('si',$student,$teacherGrade);}else{$stmt=$conn->prepare("SELECT a.STUDENT_ID,COALESCE(s.STUDENT_NAME,a.STUDENT_NAME) STUDENT_NAME,s.SECTION,a.TIME_IN,a.TIME_OUT FROM attendance a INNER JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) WHERE DATE(a.TIME_IN)=? AND (?='all' OR s.SECTION=?) AND (?='' OR a.STUDENT_ID=?) AND s.GRADE=? ORDER BY s.SECTION,STUDENT_NAME");$stmt->bind_param('sssssi',$date,$section,$section,$student,$student,$teacherGrade);}
$stmt->execute();$result=$stmt->get_result();$rows=[];while($row=$result->fetch_assoc()){$timeIn=new DateTimeImmutable($row['TIME_IN']);$timeOut=empty($row['TIME_OUT'])?null:new DateTimeImmutable($row['TIME_OUT']);$rows[]=[$row['STUDENT_ID'],$row['STUDENT_NAME'],$row['SECTION'],$timeIn->format('Y-m-d'),$timeIn->format('g:i:s A'),$timeOut?$timeOut->format('g:i:s A'):'',$timeOut?'Dismissed':'Present'];}
$fileSuffix=$allDates?'all-dates':$date;downloadAttendanceXlsx('attendance-'.preg_replace('/[^A-Za-z0-9_-]/','_',$section).'-'.$fileSuffix.'.xlsx',['Student ID','Student Name','Section','Date','Time In','Time Out','Status'],$rows);
